from pathlib import Path


def replace_once(path, old, new):
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'missing expected block in {path}: {old[:120]!r}')
    if text.count(old) != 1:
        raise SystemExit(f'expected one block in {path}, found {text.count(old)}')
    p.write_text(text.replace(old, new, 1), encoding='utf-8')

# Version metadata.
Path('VERSION.txt').write_text('1.2.37\n', encoding='utf-8')
replace_once('README.md', '当前稳定版本：**v1.2.36**', '当前稳定版本：**v1.2.37**')
